The greedy training objective is thus given recursively by defining $P_j$:
\begin{equation}
\min_{\theta_j,\gamma_j}\hat{\mathcal{L}}(\bm{X}_{j}, Y;\theta_{j},\gamma_{j})\tag{$P_j$}\label{eq:dap},

\end{equation}
where $\bm{X}_{j} =f_{\theta_{j-1}^*}(\bm{X}_{j-1})$ and $\theta_{j-1}^*$ is the minimizer of Problem

\begin{equation}
\min_{\theta_j,\gamma_j}\hat{\mathcal{L}}(\bm{X}_{j}, Y;\theta_{j},\gamma_{j})\tag{$P_j$}\label{eq:dap},

\end{equation}

We consider the SGD scheme with learning rate $\{\eta_t\}_t$:
\begin{equation}
\hspace{-0.5em}\Theta^{t+1}_{j}=\Theta^t_j-\eta_t \nabla_{\Theta_j} \ell(Z_{j-1}^t;\Theta_j^t),
\end{equation}\vspace{-3pt}
where \(Z^t_{j-1}\sim p_{j-1}^t\).

\begin{equation}
\hspace{-0.5em}\Theta^{t+1}_{j}=\Theta^t_j-\eta_t \nabla_{\Theta_j} \ell(Z_{j-1}^t;\Theta_j^t),
\end{equation}

\label{lemma:main}Under Assumptions 1, 3 and 4, we have:
\begin{eqnarray*}
\mathbb{E}[\mathcal{L}(\Theta_j^{t+1})] & \leq & \mathbb{E}[\mathcal{L}(\Theta_j^{t})]+\frac{LG}{2}\eta_t^2\,\\
{} & {} & -\eta_t\big(\mathbb{E}[\Vert\nabla\mathcal{L}(\Theta_j^t)\Vert^2] -\sqrt{2}Gc^t_{j-1}\big).
\end{eqnarray*}

\begin{eqnarray*}
\mathbb{E}[\mathcal{L}(\Theta_j^{t+1})] & \leq & \mathbb{E}[\mathcal{L}(\Theta_j^{t})]+\frac{LG}{2}\eta_t^2\,\\
{} & {} & -\eta_t\big(\mathbb{E}[\Vert\nabla\mathcal{L}(\Theta_j^t)\Vert^2] -\sqrt{2}Gc^t_{j-1}\big).
\end{eqnarray*}

Under Assumptions 1, 2, 3 and 4, each term of the following equation converges:
\vspace{-5pt}
\begin{align}
\sum_{t=0}^T \eta_t
\mathbb{E}[\Vert\nabla\mathcal{L}(\Theta_j^t)\Vert^2] &\leq  \mathbb{E}[\mathcal{L}(\Theta^0_j)]\nonumber\\
&+G\sum_{t=0}^T\eta_t\left(\sqrt{2c_{j-1}^t}+\frac{L\eta_t}{2}\right)\nonumber.
\end{align}

\begin{align}
\sum_{t=0}^T \eta_t
\mathbb{E}[\Vert\nabla\mathcal{L}(\Theta_j^t)\Vert^2] &\leq  \mathbb{E}[\mathcal{L}(\Theta^0_j)]\nonumber\\
&+G\sum_{t=0}^T\eta_t\left(\sqrt{2c_{j-1}^t}+\frac{L\eta_t}{2}\right)\nonumber.
\end{align}

 The sequence of expected gradient norm accumulates around 0 at the following rate:
\begin{equation}
\inf_{t\leq T}\mathbb{E}[\Vert \nabla\mathcal{L}(\Theta_j^t)\Vert^2]\leq\mathcal{O}\left(\frac{\sum_{t=0}^T\sqrt{c_{j-1}^t}\eta_t}{\sum_{t=0}^T\eta_t}\right)\,.\end{equation}

